content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --radius: 8px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #6366f1;
    --primary-hover: #4f46e5;
    --bg-color: #111827;
    --card-bg: #1f2937;
    --text-main: #f9fafb;
    --text-muted: #9ca3af;
    --border-color: #374151;
    --danger-color: #f87171;
    --danger-hover: #ef4444;
    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -1px rgba(0, 0, 0, 0.18);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
}

.app-container {
  width: 100%;
  max-width: 500px;
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  margin-top: 20px;
}

.header {
  margin-bottom: 24px;
  text-align: center;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
}

.input-form {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
}

.input-field {
  flex: 1;
  padding: 10px 14px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  outline: none;
  background-color: var(--card-bg);
  color: var(--text-main);
  transition: border-color 0.2s;
}

.input-field:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

.btn {
  padding: 10px 16px;
  font-size: 1rem;
  font-weight: 500;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  background-color: rgba(0, 0, 0, 0.02);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  transition: background-color 0.2s;
}

.todo-item:hover {
  background-color: rgba(0, 0, 0, 0.04);
}

@media (prefers-color-scheme: dark) {
  .todo-item {
    background-color: rgba(255, 255, 255, 0.03);
  }
  .todo-item:hover {
    background-color: rgba(255, 255, 255, 0.06);
  }
}

.todo-checkbox {
  width: 18px;
  height: 18px;
  cursor: pointer;
  accent-color: var(--primary-color);
}

.todo-text {
  flex: 1;
  margin-left: 12px;
  font-size: 1rem;
  word-break: break-all;
  color: var(--text-main);
}

.todo-text-completed {
  text-decoration: line-through;
  color: var(--text-muted);
}

.btn-delete {
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 1.25rem;
  padding: 4px 8px;
  border-radius: 4px;
  transition: color 0.2s, background-color 0.2s;
}

.btn-delete:hover {
  color: var(--danger-color);
  background-color: rgba(239, 68, 68, 0.1);
}

.empty-message {
  text-align: center;
  color: var(--text-muted);
  padding: 24px 0;
  font-size: 0.95rem;
}

@media (max-width: 480px) {
  body {
    padding: 10px;
  }

  .app-container {
    padding: 16px;
    margin-top: 10px;
  }

  .title {
    font-size: 1.5rem;
  }

  .input-form {
    flex-direction: column;
  }

  .btn {
    width: 100%;
  }
}

/**
 * TODOアイテムのデータ構造を定義するインターフェース
 */
export interface TodoItem {
  /** タスクの一意の識別子 */
  id: string;
  /** タスクの内容 */
  text: string;
  /** タスクが完了したかどうか */
  completed: boolean;
}

/**
 * フィルターの状態を表す型
 */
export type FilterType = 'all' | 'active' | 'completed';

/**
 * TodoInputコンポーネントのプロパティを定義するインターフェース
 */
export interface TodoInputProps {
  /** 新しいタスクを追加する際のコールバック関数 */
  onAdd: (text: string) => void;
}

/**
 * TodoListコンポーネントのプロパティを定義するインターフェース
 */
export interface TodoListProps {
  /** 表示するTODOアイテムの配列 */
  todos: TodoItem[];
  /** タスクの完了状態を切り替える際のコールバック関数 */
  onToggle: (id: string) => void;
  /** タスクを削除する際のコールバック関数 */
  onDelete: (id: string) => void;
}

import { useState, FormEvent } from 'react';
import { TodoInputProps } from '../types';

export default function TodoInput({ onAdd }: TodoInputProps) {
  const [text, setText] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!text.trim()) {
      setError('タスクを入力してください。');
      return;
    }
    if (text.length > 100) {
      setError('タスクは100文字以内で入力してください。');
      return;
    }
    setError('');
    onAdd(text.trim());
    setText('');
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (val.length <= 100) {
      setText(val);
      if (error) setError('');
    } else {
      setError('タスクは100文字以内で入力してください。');
    }
  };

  return (
    <div style={{ marginBottom: '24px' }}>
      <form className="input-form" onSubmit={handleSubmit} style={{ marginBottom: error ? '4px' : '0' }}>
        <input
          type="text"
          className="input-field"
          placeholder="新しいタスクを入力... (100文字まで)"
          value={text}
          onChange={handleChange}
          maxLength={100}
        />
        <button type="submit" className="btn btn-primary">
          追加
        </button>
      </form>
      {error && <p style={{ color: 'var(--danger-color)', fontSize: '0.85rem', marginLeft: '2px' }}>{error}</p>}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { TodoListProps, TodoItem } from '../types';

export default function TodoList({ todos = [], onToggle, onDelete }: TodoListProps) {
  const [localTodos, setLocalTodos] = useState<TodoItem[]>(todos);

  useEffect(() => {
    setLocalTodos(todos);
  }, [todos]);

  const handleMoveUp = (index: number) => {
    if (index === 0) return;
    const newTodos = [...localTodos];
    const temp = newTodos[index];
    newTodos[index] = newTodos[index - 1];
    newTodos[index - 1] = temp;
    setLocalTodos(newTodos);
  };

  const handleMoveDown = (index: number) => {
    if (index === localTodos.length - 1) return;
    const newTodos = [...localTodos];
    const temp = newTodos[index];
    newTodos[index] = newTodos[index + 1];
    newTodos[index + 1] = temp;
    setLocalTodos(newTodos);
  };

  const handleClearCompleted = () => {
    localTodos.forEach((todo) => {
      if (todo.completed) {
        onDelete?.(todo.id);
      }
    });
  };

  if (todos.length === 0) {
    return (
      <div className="empty-message" style={{ padding: '32px 0', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
        <span style={{ fontSize: '2rem' }}>📝</span>
        <p>タスクがありません。新しいタスクを追加してください。</p>
      </div>
    );
  }

  const hasCompleted = localTodos.some((todo) => todo.completed);

  return (
    <div>
      {hasCompleted && (
        <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '12px' }}>
          <button
            type="button"
            className="btn"
            style={{ fontSize: '0.85rem', padding: '6px 12px', backgroundColor: '#f3f4f6', color: 'var(--text-muted)' }}
            onClick={handleClearCompleted}
          >
            完了済みを削除
          </button>
        </div>
      )}
      <ul className="todo-list">
        {localTodos.map((todo, index) => (
          <li key={todo.id} className="todo-item" style={{ gap: '8px' }}>
            <input
              type="checkbox"
              className="todo-checkbox"
              checked={todo.completed}
              onChange={() => onToggle?.(todo.id)}
            />
            <span
              className={`todo-text ${todo.completed ? 'todo-text-completed' : ''}`}
            >
              {todo.text}
            </span>
            <div style={{ display: 'flex', gap: '4px' }}>
              <button
                type="button"
                className="btn-delete"
                onClick={() => handleMoveUp(index)}
                disabled={index === 0}
                aria-label="上に移動"
                style={{ fontSize: '1rem', opacity: index === 0 ? 0.3 : 1 }}
              >
                ↑
              </button>
              <button
                type="button"
                className="btn-delete"
                onClick={() => handleMoveDown(index)}
                disabled={index === localTodos.length - 1}
                aria-label="下に移動"
                style={{ fontSize: '1rem', opacity: index === localTodos.length - 1 ? 0.3 : 1 }}
              >
                ↓
              </button>
              <button
                type="button"
                className="btn-delete"
                onClick={() => onDelete?.(todo.id)}
                aria-label="削除"
              >
                ×
              </button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { TodoItem, FilterType } from './types';
import TodoInput from './components/TodoInput';
import TodoList from './components/TodoList';

const STORAGE_KEY = 'react-todo-app-items';

export default function App() {
  const [todos, setTodos] = useState<TodoItem[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        return JSON.parse(saved);
      }
    } catch (e) {
      console.error('Failed to load todos from localStorage:', e);
    }
    return [
      { id: '1', text: 'Reactのプロジェクトを作成する', completed: true },
      { id: '2', text: 'やることリストの機能を実装する', completed: false },
      { id: '3', text: 'コンポーネントをスタイリングする', completed: false },
    ];
  });

  const [filter, setFilter] = useState<FilterType>('all');

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) {
      console.error('Failed to save todos to localStorage:', e);
    }
  }, [todos]);

  const handleAdd = (text: string) => {
    const newItem: TodoItem = {
      id: Date.now().toString(),
      text,
      completed: false,
    };
    setTodos([newItem, ...todos]);
  };

  const handleToggle = (id: string) => {
    setTodos(
      todos.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  };

  const handleDelete = (id: string) => {
    setTodos(todos.filter((todo) => todo.id !== id));
  };

  const filteredTodos = todos.filter((todo) => {
    if (filter === 'active') return !todo.completed;
    if (filter === 'completed') return todo.completed;
    return true;
  });

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">やることリスト</h1>
      </header>
      <TodoInput onAdd={handleAdd} />

      <div style={{ display: 'flex', gap: '8px', marginBottom: '16px', justifyContent: 'center' }}>
        <button
          type="button"
          className={`btn ${filter === 'all' ? 'btn-primary' : ''}`}
          style={filter !== 'all' ? { backgroundColor: 'var(--border-color)', color: 'var(--text-main)' } : {}}
          onClick={() => setFilter('all')}
        >
          すべて
        </button>
        <button
          type="button"
          className={`btn ${filter === 'active' ? 'btn-primary' : ''}`}
          style={filter !== 'active' ? { backgroundColor: 'var(--border-color)', color: 'var(--text-main)' } : {}}
          onClick={() => setFilter('active')}
        >
          未完了
        </button>
        <button
          type="button"
          className={`btn ${filter === 'completed' ? 'btn-primary' : ''}`}
          style={filter !== 'completed' ? { backgroundColor: 'var(--border-color)', color: 'var(--text-main)' } : {}}
          onClick={() => setFilter('completed')}
        >
          完了済み
        </button>
      </div>

      <TodoList todos={filteredTodos} onToggle={handleToggle} onDelete={handleDelete} />
    </div>
  );
}
